package app.kinnect.live;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

public class StoreActivity extends Activity implements StoreBilling.Events {
 public void setContentView(View view){super.setContentView(CommerceChrome.wrap(this,view));}
 @Override protected void attachBaseContext(Context base){super.attachBaseContext(I18n.localized(base));}
 private JSONObject catalog;private final Map<String,String> prices=new HashMap<>();private StoreBilling billing;private LinearLayout body;private String selectedTab="style";private boolean busy;private final java.util.ArrayDeque<String[]> receiptQueue=new java.util.ArrayDeque<>();
 private void styleBars(){int v=WebTheme.isDark(this)?1:0;getWindow().setStatusBarColor(WebDesign.BG[v]);getWindow().setNavigationBarColor(WebDesign.BG[v]);getWindow().getDecorView().setSystemUiVisibility(v==0?View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0);}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private String tr(String s){return I18n.t(s);}
 private int variant(){return WebTheme.isDark(this)?1:0;}
 private GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView label(String text,int size){TextView v=new KinnectText(this);v.setText(text);v.setTextSize(size);v.setTypeface(ApprovedTypography.font(this,Typeface.NORMAL));v.setTextColor(WebDesign.INK[variant()]);v.setPadding(0,dp(5),0,dp(5));return v;}
 private Button button(String title,Runnable action){Button b=new KinnectButton(this);b.setText(title);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(ApprovedTypography.font(this,Typeface.BOLD));b.setMinHeight(dp(46));b.setTextColor(Color.WHITE);b.setBackground(gradient(0xff7c3aed,0xffc026d3,14));b.setPadding(dp(12),dp(9),dp(12),dp(9));b.setOnClickListener(v->action.run());return b;}
 private boolean owns(String id){JSONArray owned=catalog==null?null:catalog.optJSONArray("owned");if(owned!=null)for(int i=0;i<owned.length();i++)if(id.equals(owned.optString(i)))return true;return false;}
 public void onCreate(Bundle saved){super.onCreate(saved);styleBars();NativeApi.shared.initialize(this,ServerConfig.DEFAULT_ORIGIN);billing=StoreBilling.create(this);ui=new CommerceUi(this);LinearLayout loading=ui.col();loading.setBackgroundColor(ui.bg);loading.addView(ui.header("Cửa hàng"));loading.addView(ui.empty("shopping_bag","Đang tải…"));setContentView(loading);load(true);}
 private void load(boolean connect){NativeApi.shared.call("GET","/api/store",null,(data,error,status)->{if(isFinishing()||isDestroyed())return;if(error!=null){message(tr("Chưa tải được cửa hàng. Hãy thử lại."));if(catalog==null){LinearLayout page=new LinearLayout(this);page.setBackgroundColor(WebDesign.BG[variant()]);page.setOrientation(1);page.setPadding(dp(20),dp(20),dp(20),dp(20));page.addView(label(tr("Chưa tải được cửa hàng."),18));page.addView(button(tr("Thử lại"),()->load(true)));page.addView(button(tr("Quay lại"),()->finish()));setContentView(page);}return;}catalog=data;draw();if(connect){List<String> ids=new ArrayList<>();JSONArray products=catalog.optJSONArray("products");for(int i=0;i<products.length();i++)ids.add(products.optJSONObject(i).optString("id"));billing.connect(ids,catalog.optString("accountId"),this);}});}
 private CommerceUi ui;private ScrollView storeScroll;
 private void selectTab(String key){selectedTab=key;storeScroll=null;draw();}
 private void storeMenu(){new Sheet(this).setTitle(tr("Cửa hàng")).setItemIcons(new String[]{"rotate_ccw","palette","info"}).setItems(new String[]{tr("Khôi phục giao dịch"),tr("Phong cách mặc định"),tr("Thông tin")},(d,n)->{if(n==0){billing.restore();load(false);}else if(n==1)apply("");else new Sheet(this).setTitle(tr("Cửa hàng")).setMessage(tr("Quyền lợi gắn với tài khoản Kinnect. Xem thử không thay đổi hồ sơ. Giá thanh toán chỉ hiển thị khi Google Play sẵn sàng.")).setPositiveButton(tr("Đóng"),null).show();}).show();}
 private void draw(){
  if(ui==null)ui=new CommerceUi(this);int scrollY=storeScroll==null?0:storeScroll.getScrollY();LinearLayout root=ui.col();root.setBackgroundColor(ui.bg);root.addView(ui.header("Cửa hàng",ui.icon("wallet","Mở ví",()->ui.go(WalletActivity.class)),ui.icon("ellipsis","Tùy chọn cửa hàng",this::storeMenu)));setContentView(root);
  LinearLayout tabs=ui.row();tabs.setPadding(ui.dp(13),ui.dp(2),ui.dp(13),ui.dp(8));for(String key:new String[]{"style","studio","owned"}){String title=key.equals("style")?"Phong cách":key.equals("studio")?"Studio":"Của tôi";Button tab=ui.action(title,null,()->selectTab(key));tab.setTextSize(12);tab.setCompoundDrawablesRelative(null,ui.glyph(key.equals("style")?"palette":key.equals("studio")?"clapperboard":"check",selectedTab.equals(key)?Color.WHITE:ui.purple,20),null,null);tab.setCompoundDrawablePadding(ui.dp(5));tab.setSelected(selectedTab.equals(key));tab.setMinLines(2);if(!selectedTab.equals(key)){tab.setTextColor(ui.purple);tab.setBackground(ui.round(ui.soft,16));}LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(0,-2,1);at.setMargins(ui.dp(3),0,ui.dp(3),0);tabs.addView(tab,at);}root.addView(tabs);
  storeScroll=new ScrollView(this);storeScroll.setTag("store:scroll");body=ui.col();body.setPadding(ui.dp(16),ui.dp(4),ui.dp(16),ui.dp(24));storeScroll.addView(body);root.addView(storeScroll,new LinearLayout.LayoutParams(-1,0,1));
  if(selectedTab.equals("style")&&catalog.optBoolean("studioProFree")){LinearLayout teaser=ui.row();teaser.setPadding(ui.dp(18),ui.dp(16),ui.dp(16),ui.dp(16));teaser.setBackground(ui.gradient());ImageView icon=new ImageView(this);icon.setImageDrawable(ui.glyph("sparkles",Color.WHITE,30));teaser.addView(icon,new LinearLayout.LayoutParams(ui.dp(38),ui.dp(40)));LinearLayout text=ui.col();text.setPadding(ui.dp(12),0,ui.dp(8),0);text.addView(ui.text("Studio Pro",18,Color.WHITE,true));text.addView(ui.text("Miễn phí trải nghiệm",11,0xffeee6ff,false));teaser.addView(text,new LinearLayout.LayoutParams(0,-2,1));ImageView arrow=new ImageView(this);arrow.setImageDrawable(ui.glyph("arrow_up_right",Color.WHITE,22));teaser.addView(arrow,new LinearLayout.LayoutParams(ui.dp(24),ui.dp(24)));teaser.setOnClickListener(v->selectTab("studio"));teaser.setContentDescription(tr("Studio Pro miễn phí"));ui.add(body,teaser,4);}
  JSONArray products=catalog.optJSONArray("products");java.util.List<JSONObject> shown=new java.util.ArrayList<>();if(products!=null)for(int i=0;i<products.length();i++){JSONObject p=products.optJSONObject(i);if(p!=null&&(selectedTab.equals("owned")?owns(p.optString("id")):selectedTab.equals(p.optString("kind"))))shown.add(p);}
  if(shown.isEmpty()){ui.add(body,ui.empty("shopping_bag","Chưa có sản phẩm"),24);if(selectedTab.equals("owned"))ui.add(body,ui.action("Khám phá","palette",()->selectTab("style")),12);}
  else if(selectedTab.equals("studio")){for(JSONObject p:shown)ui.add(body,product(p),12);}
  else for(int i=0;i<shown.size();i+=2){LinearLayout row=ui.row();row.setGravity(Gravity.TOP);for(int col=0;col<2;col++){LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(0,-2,1);at.setMargins(col==0?0:ui.dp(6),0,col==0?ui.dp(6):0,0);if(i+col<shown.size())row.addView(product(shown.get(i+col)),at);else row.addView(new View(this),at);}ui.add(body,row,12);}
  final ScrollView current=storeScroll;current.post(()->current.scrollTo(0,scrollY));
 }
 private void showProduct(JSONObject p){String id=p.optString("id");String description=p.optString(I18n.current().equals("en")?"descriptionEn":"description");if(id.equals("kinnect_studio_pro")&&catalog.optBoolean("studioProFree"))description=tr("Miễn phí trải nghiệm")+"\n\n"+description.replace("Mua một lần, dùng trên tài khoản này.","").replace("One-time purchase for this account.","");if(!owns(id)&&!(id.equals("kinnect_studio_pro")&&catalog.optBoolean("studioProFree"))&&!prices.containsKey(id))description+="\n\n"+tr("Giá dự kiến, chưa phải giá thanh toán")+": "+java.text.NumberFormat.getIntegerInstance(new java.util.Locale("vi","VN")).format(p.optInt("referenceVnd"))+"đ";new Sheet(this).setTitle(p.optString("name")).setMessage(description+"\n\n"+tr("Xem thử không thay đổi hồ sơ hoặc cấp quyền sử dụng.")).setView(preview(p)).setPositiveButton(tr("Đóng"),null).show();}
 private View product(JSONObject p){
  String id=p.optString("id");boolean studio=p.optString("kind").equals("studio"),free=studio&&catalog.optBoolean("studioProFree"),owned=owns(id),applied=id.equals(catalog.optString("appearance"));LinearLayout card=ui.section();card.setTag("store:product:"+id);card.setPadding(ui.dp(10),ui.dp(10),ui.dp(10),ui.dp(12));StoreArt art=new StoreArt(p);art.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);card.addView(art,new LinearLayout.LayoutParams(-1,ui.dp(studio?148:104)));TextView name=ui.text(p.optString("name"),studio?20:16,ui.ink,true);name.setPadding(ui.dp(2),ui.dp(10),0,ui.dp(4));card.addView(name);TextView status=ui.text(free?"Miễn phí":owned?(applied?"Đang dùng":"Đã có"):(Distribution.PLAY&&catalog.optBoolean("billingReady")&&prices.containsKey(id)?"Mua một lần":"Chưa mở bán"),11,free||owned?ui.purple:ui.muted,false);status.setPadding(ui.dp(2),0,0,ui.dp(8));card.addView(status);card.setContentDescription(p.optString("name")+" · "+tr("Xem thử"));card.setOnClickListener(v->showProduct(p));
  if(free||owned){Button use=ui.action(studio?"Mở Studio":applied?"Đang dùng":"Áp dụng",null,()->{if(studio)chooseMedia();else apply(id);});if(applied&&!studio){use.setEnabled(false);use.setAlpha(.55f);}card.addView(use,new LinearLayout.LayoutParams(-1,-2));}
  else if(Distribution.PLAY&&catalog.optBoolean("billingReady")&&prices.containsKey(id)){Button buy=ui.action(prices.get(id),null,()->{if(busy)return;new Sheet(this).setTitle(p.optString("name")).setMessage(tr("Mua một lần")+" · "+prices.get(id)+"\n\n"+tr("Quyền lợi gắn với tài khoản Kinnect đang đăng nhập.")).setPositiveButton(tr("Tiếp tục với Google Play"),(d,w)->billing.buy(id)).setNegativeButton(tr("Hủy"),null).show();});buy.setEnabled(!busy);card.addView(buy,new LinearLayout.LayoutParams(-1,-2));}
  else{TextView view=ui.badge("Xem thử");view.setCompoundDrawablesRelative(ui.glyph("eye",ui.purple,16),null,null,null);view.setCompoundDrawablePadding(ui.dp(6));view.setMinHeight(ui.dp(44));card.addView(view,new LinearLayout.LayoutParams(-1,-2));}
  return card;
 }
 private GradientDrawable gradient(int a,int b,int radius){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{a,b});g.setCornerRadius(dp(radius));return g;}
 private final class StoreArt extends View {
  private final JSONObject product;private final Paint paint=new Paint(3);
  StoreArt(JSONObject value){super(StoreActivity.this);product=value;setContentDescription(value.optString("name")+" · "+tr("Xem thử"));}
  private void box(Canvas c,float l,float t,float r,float b,float radius,int color){paint.setShader(null);paint.setColor(color);c.drawRoundRect(l,t,r,b,radius,radius,paint);}
  protected void onDraw(Canvas source){super.onDraw(source);Canvas c=source;int save=c.save();c.scale(getWidth()/300f,getHeight()/178f);JSONArray colors=product.optJSONArray("colors");int a=Color.parseColor(colors.optString(0)),b=Color.parseColor(colors.optString(1));paint.setShader(new LinearGradient(0,0,300,178,a,b,Shader.TileMode.CLAMP));c.drawRoundRect(0,0,300,178,18,18,paint);paint.setShader(null);paint.setColor(0x33ffffff);c.drawCircle(55,30,110,paint);paint.setColor(0x22ffffff);c.drawCircle(265,160,85,paint);
   if(product.optString("kind").equals("studio")){for(int i=0;i<3;i++){float x=55+i*65;box(c,x,30+(i==1?-8:4),x+55,132+(i==1?8:0),10,0x55ffffff);android.graphics.drawable.Drawable icon=WebIcons.load(StoreActivity.this,i==0?"sparkles":i==1?"play":"clapperboard");icon.setTint(Color.WHITE);icon.setBounds((int)x+15,65,(int)x+40,90);icon.draw(c);}}
   else{paint.setColor(0x66ffffff);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1);c.drawCircle(139,78,70,paint);paint.setStrokeWidth(4);c.drawCircle(125,70,36,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0x44ffffff);c.drawCircle(125,70,32,paint);paint.setColor(Color.WHITE);paint.setTypeface(ApprovedTypography.font(StoreActivity.this,Typeface.BOLD));paint.setTextSize(32);paint.setTextAlign(Paint.Align.CENTER);c.drawText("K",125,81,paint);box(c,157,85,246,124,12,0xeeffffff);box(c,170,96,230,101,3,a);box(c,170,108,212,112,3,b);}
   paint.setShader(null);paint.setColor(Color.WHITE);paint.setTextAlign(Paint.Align.CENTER);paint.setTypeface(ApprovedTypography.font(StoreActivity.this,Typeface.BOLD));paint.setTextSize(9);c.restoreToCount(save);
  }
 }
 private View preview(JSONObject product){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),dp(12),dp(12),dp(12));JSONArray colors=product.optJSONArray("colors");int color=Color.parseColor(colors.optString(0));TextView demo=label(product.optString("kind").equals("studio")?"Aurora · Travel · Cinema":"Kinnect · "+tr("Hồ sơ minh họa"),22);demo.setTextColor(color);demo.setGravity(Gravity.CENTER);GradientDrawable frame=round(WebDesign.CARD[variant()],18);frame.setStroke(dp(3),color);demo.setPadding(dp(16),dp(18),dp(16),dp(18));demo.setBackground(frame);box.addView(demo);TextView chat=label(tr("Xin chào! Đây là bản xem thử."),16);chat.setTextColor(Color.WHITE);chat.setPadding(dp(16),dp(16),dp(16),dp(16));chat.setBackground(round(color,18));LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(-1,-2);at.topMargin=dp(18);box.addView(chat,at);return box;}
 private void chooseMedia(){new Sheet(this).setTitle("Studio Pro").setItemIcons(new String[]{"image","clapperboard"}).setItems(new String[]{tr("Ảnh"),tr("Video")},(d,w)->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(w==0?"image/*":"video/*"),w==0?701:700);}catch(Exception e){message(tr("Không mở được thư viện tệp."));}}).setNegativeButton(tr("Quay lại"),null).show();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==701&&result==RESULT_OK&&data!=null&&data.getData()!=null)startActivity(new Intent(this,PhotoEditActivity.class).setData(data.getData()).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));if(request==700&&result==RESULT_OK&&data!=null&&data.getData()!=null)startActivity(new Intent(this,MediaEditActivity.class).setData(data.getData()).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra("store_pro",true));}
 private void apply(String id){try{NativeApi.shared.call("POST","/api/store/style",new JSONObject().put("productId",id),(data,error,status)->{if(error!=null)message(error);else{message(tr("Đã áp dụng phong cách."));load(false);}});}catch(Exception e){message(tr("Chưa áp dụng được phong cách."));}}
 public void prices(Map<String,String> value){runOnUiThread(()->{if(isDestroyed())return;prices.clear();prices.putAll(value);if(catalog!=null)draw();});}
 public void receipt(String product,String token){runOnUiThread(()->{if(isDestroyed())return;receiptQueue.add(new String[]{product,token});verifyNext();});}
 private void verifyNext(){if(busy||receiptQueue.isEmpty()||isDestroyed())return;busy=true;String[] receipt=receiptQueue.remove();try{NativeApi.shared.call("POST","/api/store/verify",new JSONObject().put("productId",receipt[0]).put("purchaseToken",receipt[1]),(data,error,status)->{busy=false;if(isDestroyed())return;message(error!=null?error:data.optString("state").equals("PURCHASED")?tr("Giao dịch đã xác minh. Quyền lợi đã được cập nhật."):tr("Giao dịch đang chờ xử lý; chưa cấp quyền lợi."));if(receiptQueue.isEmpty())load(false);else verifyNext();});}catch(Exception e){busy=false;message(tr("Chưa xác minh được giao dịch."));verifyNext();}}
 public void message(String text){runOnUiThread(()->{if(!isDestroyed())Toast.makeText(this,I18n.t(text),Toast.LENGTH_LONG).show();});}
 protected void onDestroy(){if(billing!=null)billing.close();super.onDestroy();}
}
